package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.assertThat;

class Java17Test {

    sealed interface Instruction permits Buy, Sell {}
    record Buy(BigDecimal amount) implements Instruction {}
    record Sell(BigDecimal amount) implements Instruction {}

    String handle(Instruction i) {
        if (i instanceof Buy b)  return "BUY " + b.amount();   // pattern matching instanceof
        if (i instanceof Sell s) return "SELL " + s.amount();
        return "UNKNOWN";
    }

    @Test
    void recordsSealedPatternMatching() {
        assertThat(handle(new Buy(new BigDecimal("50000")))).isEqualTo("BUY 50000");
        assertThat(handle(new Sell(new BigDecimal("20000")))).isEqualTo("SELL 20000");
    }
}
